/* 团队工具与技能目录：纯浏览器内存演示，刷新后恢复；不保存明文凭据。 */
const tlState={tab:'mcp',preview:'正常',version:12};
const tlServers=[
 {id:'mcp1',name:'代码仓库连接',transport:'Streamable HTTP',provider:'代码服务',address:'由团队配置的服务地址',auth:'访问令牌',sealed:true,expired:false,enabled:true,grants:['project:p1','agent:ada'],calls:128,health:'正常'},
 {id:'mcp2',name:'工单连接',transport:'打包的 stdio',provider:'工单服务',address:'packages/issues-mcp',auth:'访问令牌',sealed:true,expired:false,enabled:true,grants:[],calls:0,health:'未授权'}
];
const tlSkills=[
 {id:'skill1',name:'billing-review',version:'1.3',hash:'9e84a612',source:'仓库',grants:['project:p1','agent:ada'],agents:2,next:'1.4',nextHash:'a32c7091',description:'核对账单金额、逐行舍入与验收证据。',files:['SKILL.md','references/amount-rules.md'],history:[['1.3','9e84a612','增加半分边界说明'],['1.2','c18b4570','增加逐行金额核对']],diff:'新增：零金额、半分边界与汇总核对步骤。'},
 {id:'skill2',name:'证据整理',version:'1.0',hash:'b970c2d4',source:'上传',grants:[],agents:0,next:null,description:'整理执行证据与未验证项，不代替平台验证或团队裁决。',files:['SKILL.md'],history:[['1.0','b970c2d4','首次上传']],diff:'当前无新版本。'}
];
const tlLocal=[{id:'local1',name:'test-first',kind:'技能',machine:'m1',path:'.agents/skills/test-first/SKILL.md',version:'2.1',hash:'5a817de2',adopted:false},{id:'local2',name:'本机版本库读取',kind:'MCP',machine:'m3',path:'本机 stdio 配置',adopted:false}];
const tlAudit=[{server:'mcp1',time:'2026-10-12 09:18',agent:'ada',tool:'读取差异',project:'p1',result:'成功'},{server:'mcp1',time:'2026-10-12 09:12',agent:'bo',tool:'读取历史',project:'p2',result:'拒绝 · 未授权'}];
const tlEvidence=[{execution:'EX-9088',agent:'ada',catalog:11,skill:'billing-review v1.3 · 9e84a612',mcp:'代码仓库连接 · 配置 v11',state:'已声明完成（未验证）'}];
const tlPresets=['GitHub','Linear','Notion','云效（Codeup / Projex）'];
const tlStyle='width:100%;padding:9px 12px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:var(--fg);font:inherit';
function tlEsc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function tlBtn(label,action,kind='',disabled=false,reason=''){return `<button type="button" class="btn ${kind}" onclick="${tlEsc(action)}" ${disabled?'disabled':''}>${label}</button>${disabled?`<span class="muted xs">${tlEsc(reason)}</span>`:''}`;}
function tlTable(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${headers.length}"><div class="empty">暂无条目，你可以添加服务器或纳入本机条目。</div></td></tr>`}</tbody></table></div>`;}
function tlKv(rows){return `<dl class="kv">${rows.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;}
function tlProject(id){const p=PROJECTS.find(p=>p.id===id);return p?tlEsc(p.name.replace(/ Billing| Console| Docs/g,'')):'未知项目';}
function tlScope(grants){return grants.length?grants.map(g=>{const [kind,id]=g.split(':');return kind==='project'?'项目：'+tlProject(id):kind==='agent'?'Agent：'+tlEsc(PEOPLE[id]?.n||id):'角色：'+tlEsc(id);}).join('<br>'):'<span class="muted">无（默认）</span>';}
function tlGet(kind,id){return (kind==='mcp'?tlServers:tlSkills).find(e=>e.id===id);}
function tlExpired(e){return e.sealed&&(e.expired||tlState.preview==='凭据过期');}
function tlSet(key,value){tlState[key]=value;closeDrawer();route();}
function tlModal(title,body,footer){openModal(`<div class="stack" style="padding:24px"><div class="row"><h3 class="grow">${title}</h3>${tlBtn('关闭','closeModal()','ghost sm')}</div>${body}<div id="tl-error" class="note danger" role="alert" hidden></div><div class="row wrap">${footer}</div></div>`);}
function tlError(text){const el=document.getElementById('tl-error');el.hidden=false;el.textContent=text;}
PAGES['tool-catalog']=()=>{
 const servers=tlState.preview==='空'?[]:tlServers,skills=tlState.preview==='空'?[]:tlSkills;
 const directory=tlState.tab==='mcp'?card('MCP 服务器',tlTable(['名称','传输方式','提供方','凭据状态','授权范围','最近 7 天调用次数','健康'],servers.map(e=>[
  tlBtn(tlEsc(e.name),`tlDetail('mcp','${e.id}')`,'ghost sm'),e.transport,tlEsc(e.provider),`${e.sealed?'<span class="mono">已封存 · ••••••••</span>':'无需凭据'}${e.sealed&&tlExpired(e)?'<br><span class="badge b-danger">凭据过期</span>':''}${e.sealed?'<br>'+tlBtn('轮换',`tlDanger('rotate','${e.id}')`,'danger sm',!e.enabled,'服务器已停用'):''}`,tlScope(e.grants),e.calls,`<span class="badge ${!e.enabled?'b-stale':tlExpired(e)?'b-danger':'b-ok'}">${!e.enabled?'已停用':tlExpired(e)?'认证失败':e.health}</span>`
 ]))+`<div class="note danger">轮换会使旧凭据失效，正在使用旧令牌的调用可能失败；需重新认证。</div>`,{icon:'plug',right:tlBtn('添加服务器','tlAdd()','primary sm')}):card('技能',tlTable(['名称','版本','内容哈希前 8 位','来源','授权范围','使用中的 Agent 数','更新'],skills.map(e=>[tlBtn(tlEsc(e.name),`tlDetail('skill','${e.id}')`,'ghost sm'),'v'+tlEsc(e.version),`<span class="mono">${e.hash}</span>`,e.source,tlScope(e.grants),e.agents,e.next?`<span class="badge b-info">可升级到 v${e.next}</span>`:'已是最新版本'])),{icon:'book-open'});
 return head('团队','工具与技能','团队统一目录 · 配置与授权在条目详情中管理。')+`<div class="row wrap" style="margin-bottom:16px"><b>状态预览</b>${['正常','空','凭据过期'].map(v=>`<button type="button" class="chip ${tlState.preview===v?'on':''}" aria-pressed="${tlState.preview===v}" onclick="tlSet('preview','${v}')">${v}</button>`).join('')}<span class="muted xs">预览不修改凭据；全部操作仅为内存演示。</span></div><div class="tabs" role="tablist">${[['mcp','MCP 服务器'],['skill','技能']].map(([k,t])=>`<button type="button" role="tab" aria-selected="${tlState.tab===k}" class="${tlState.tab===k?'on':''}" onclick="tlSet('tab','${k}')">${t}</button>`).join('')}</div><div class="stack">${tlState.preview==='凭据过期'?'<div class="note danger" role="status">凭据过期：相关 MCP 调用会被拒绝。请在条目详情中轮换凭据，需重新认证；技能仍按授权同步。</div>':''}${directory}${card('执行机本机自带（未纳入团队目录）',tlTable(['名称','类型','机器','检测来源','状态','操作'],(tlState.preview==='空'?[]:tlLocal.filter(e=>!e.adopted)).map(e=>[tlEsc(e.name),e.kind,tlEsc(MACHINES.find(m=>m.id===e.machine)?.n||e.machine),`<span class="mono">${tlEsc(e.path)}</span>`,'<span class="badge b-warn">本机自带，未纳入团队目录</span>',tlBtn('纳入团队目录',`tlAdopt('${e.id}')`,'sm')]))+'<div class="note warn">本机检测不代表实时连接健康，也不代表已获团队授权。纳入后默认无授权，请在条目详情中编辑。</div>',{icon:'monitor'})}${card('分发与执行证据',tlKv([['当前目录版本','v'+tlState.version],['分发时机','执行开始时'],['默认授权','无；按项目 / 角色 / Agent 显式授予'],['凭据交付','短期、限范围的令牌或本地代理']])+`<div class="note info">凭据由平台封存，执行机只拿到短期、限范围的令牌或本地代理，Agent 看不到明文。</div><p class="small">执行开始时，执行机按授权同步技能、注入 MCP 配置；执行记录所用目录版本，作为证据。技能升级只对之后开始的执行生效，历史证据保留原版本。</p>`+tlTable(['执行','Agent','所用目录版本','技能快照','MCP 配置快照','声明状态'],(tlState.preview==='空'?[]:tlEvidence).map(e=>[tlEsc(e.execution),who(e.agent),'v'+e.catalog,tlEsc(e.skill),tlEsc(e.mcp),e.state])),{icon:'shield-check'})}</div>`;
};
TITLES['tool-catalog']='工具与技能';
NAVPARENT['tool-catalog']='tool-catalog';
function tlGrantOptions(){return [...PROJECTS.map(p=>['project:'+p.id,'项目：'+p.name.replace(/ Billing| Console| Docs/g,'')]),...['执行者','评审员','协调员'].map(r=>['role:'+r,'角色：'+r]),...Object.keys(PEOPLE).filter(k=>PEOPLE[k].k==='a').map(k=>['agent:'+k,'Agent：'+PEOPLE[k].n])];}
function tlGrantPanel(kind,e){return card('授权编辑',`<div class="note info">默认无授权。你可按项目、角色或 Agent 授予使用范围；挂载技能不会增加角色权限。</div><div class="stack">${tlGrantOptions().map(([v,t])=>`<label class="row small"><input type="checkbox" name="tl-grant" value="${tlEsc(v)}" ${e.grants.includes(v)?'checked':''} ${e.enabled===false?'disabled':''}>${tlEsc(t)}</label>`).join('')}</div><div style="margin-top:16px">${tlBtn('保存授权',`tlSaveGrants('${kind}','${e.id}')`,'primary',e.enabled===false,'服务器已停用，不可编辑授权')}</div>`);}
function tlDetail(kind,id){const e=tlGet(kind,id);if(!e)return;const heading=`<div class="row wrap" style="padding:20px"><h3 class="grow">${tlEsc(e.name)}</h3>${tlBtn('关闭并返回目录','closeDrawer()','ghost sm')}</div>`;
 const body=kind==='mcp'?card('连接详情',tlKv([['名称',tlEsc(e.name)],['地址 / 包路径',tlEsc(e.address)],['传输方式',e.transport],['提供方',tlEsc(e.provider)],['认证方式',e.auth],['凭据',e.sealed?'已封存 · ••••••••':'无需凭据'],['健康',!e.enabled?'已停用':tlExpired(e)?'凭据过期 · 认证失败':e.health],['最近 7 天调用次数',e.calls]])+'<div class="note info">Agent 看不到明文；凭据不回显。</div>')+tlGrantPanel(kind,e)+card('调用审计',tlTable(['时间','Agent','工具名','项目','结果'],tlAudit.filter(a=>a.server===id).map(a=>[a.time,who(a.agent),tlEsc(a.tool),tlProject(a.project),`<span class="badge ${a.result==='成功'?'b-ok':'b-danger'}">${a.result}</span>`])))+card('危险操作',`<div class="note danger">轮换会使旧凭据失效，相关在途调用可能失败。停用后拒绝后续工具调用，可能导致运行中的执行失败；历史审计保留。需重新认证。</div><div class="row wrap">${tlBtn('轮换',`tlDanger('rotate','${id}')`,'danger',!e.enabled||!e.sealed,!e.enabled?'服务器已停用':'此连接无需凭据')}${tlBtn('停用',`tlDanger('disable','${id}')`,'danger',!e.enabled,'服务器已停用')}</div>`):card('说明与文件清单',`<p>${tlEsc(e.description)}</p>`+tlKv([['当前版本','v'+e.version],['内容哈希前 8 位',`<span class="mono">${e.hash}</span>`],['来源',e.source],['使用中的 Agent 数',e.agents]])+e.files.map(f=>`<p class="mono small">${tlEsc(f)}</p>`).join(''))+card('版本历史与差异',tlTable(['版本','内容哈希前 8 位','变更说明'],e.history.map(r=>['v'+r[0],r[1],tlEsc(r[2])]))+`<p>${e.next?'v'+e.version+' → v'+e.next+'：':''}${tlEsc(e.diff)}</p><div class="note info">升级只对之后开始的执行生效，运行中的执行与历史证据保留原版本。</div>${tlBtn(e.next?'升级到 v'+e.next:'升级',`tlUpgrade('${id}')`,'primary',!e.next,'当前没有可升级版本')}`)+tlGrantPanel(kind,e);
 openDrawer(heading+`<div class="stack" style="padding:0 20px 24px">${body}</div>`);
}
function tlSaveGrants(kind,id){const e=tlGet(kind,id);if(!e||e.enabled===false)return;e.grants=Array.from(document.querySelectorAll('#drawer input[name="tl-grant"]:checked')).map(n=>n.value);tlState.version++;route();tlDetail(kind,id);toast('授权已保存（内存演示），后续执行按授权分发');}
function tlUpgrade(id){const e=tlGet('skill',id);if(!e?.next)return;tlModal('升级技能',`<p>${tlEsc(e.name)}：v${e.version} → v${e.next}</p><p>${tlEsc(e.diff)}</p><div class="note info">升级只对之后开始的执行生效；运行中的执行与历史证据不变。</div>`,tlBtn('取消','closeModal()')+tlBtn('确认升级',`tlConfirmUpgrade('${id}')`,'primary'));}
function tlConfirmUpgrade(id){const e=tlGet('skill',id);if(!e?.next)return;e.version=e.next;e.hash=e.nextHash;e.history.unshift([e.version,e.hash,e.diff]);e.next=null;e.diff='当前无新版本。';tlState.version++;closeModal();route();tlDetail('skill',id);toast('目录已升级（内存演示）');}
function tlField(label,id,value='',type='text'){return `<label class="stack small">${label}<input id="${id}" type="${type}" value="${tlEsc(value)}" style="${tlStyle}" ${type==='password'?'autocomplete="new-password"':''}></label>`;}
function tlAdd(preset){tlModal('添加服务器',`<div class="row wrap"><span>推荐预设</span>${tlPresets.map((p,i)=>tlBtn(tlEsc(p),`tlPreset(${i})`,'sm')).join('')}</div>${tlField('名称','tl-name',preset||'')}${tlField('提供方','tl-provider',preset||'')}<label class="stack small">传输方式<select id="tl-transport" style="${tlStyle}"><option>Streamable HTTP</option><option>打包的 stdio</option></select></label>${tlField('地址 / 打包的 stdio 包路径','tl-address')}<label class="stack small">认证方式<select id="tl-auth" style="${tlStyle}" onchange="tlAuthFields()"><option>访问令牌</option><option>OAuth 授权</option><option>无需认证</option></select></label>${tlField('凭据（只提交一次，不回显）','tl-secret','','password')}<div class="note info">地址由你配置，预设不内置域名。OAuth 授权在实际接入时完成；本原型以一次性提交的授权凭据模拟。凭据由平台封存，不保存在演示数据中。</div>`,tlBtn('取消','tlCancelAdd()')+tlBtn('添加服务器','tlSubmitAdd()','primary'));}
function tlPreset(index){const p=tlPresets[index];document.getElementById('tl-name').value=p;document.getElementById('tl-provider').value=p;document.getElementById('tl-transport').value='Streamable HTTP';document.getElementById('tl-auth').value=index===3?'访问令牌':'OAuth 授权';tlAuthFields();}
function tlAuthFields(){const secret=document.getElementById('tl-secret');secret.disabled=document.getElementById('tl-auth').value==='无需认证';if(secret.disabled)secret.value='';}
function tlCancelAdd(){document.getElementById('tl-secret').value='';closeModal();}
function tlSubmitAdd(){const name=document.getElementById('tl-name').value.trim(),provider=document.getElementById('tl-provider').value.trim(),address=document.getElementById('tl-address').value.trim(),transport=document.getElementById('tl-transport').value,auth=document.getElementById('tl-auth').value,secret=document.getElementById('tl-secret');if(!name||!provider||!address)return tlError('请填写名称、提供方和地址 / 包路径。');if(transport==='Streamable HTTP'){try{const u=new URL(address);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error();}catch{return tlError('请填写不含账号和密码的 HTTP 服务地址。');}}if(auth!=='无需认证'&&!secret.value.trim())return tlError('请提交一次认证凭据；平台封存后不回显。');secret.value='';const e={id:'mcp'+(tlServers.length+1),name,provider,address,transport,auth,sealed:auth!=='无需认证',expired:false,enabled:true,grants:[],calls:0,health:'待检测'};tlServers.push(e);tlState.version++;tlState.preview='正常';tlState.tab='mcp';closeModal();route();tlDetail('mcp',e.id);toast('服务器已添加，默认无授权（内存演示）');}
function tlDanger(action,id){const e=tlGet('mcp',id);if(!e?.enabled||action==='rotate'&&!e.sealed)return;const rotate=action==='rotate';tlModal(rotate?'轮换凭据':'停用服务器',`<p>${tlEsc(e.name)}</p><div class="note danger">${rotate?'旧凭据将失效，正在使用旧令牌的调用可能失败。':'后续工具调用将被拒绝，运行中的执行可能失败；历史审计保留。'}需重新认证。</div>${rotate?tlField('新凭据（只提交一次，不回显）','tl-new-secret','','password'):''}<div class="note warn">本原型仅模拟重新认证，不执行真实身份校验或平台封存。</div>`,tlBtn('取消','closeModal()')+tlBtn('模拟重新认证并'+(rotate?'轮换':'停用'),`tlConfirmDanger('${action}','${id}')`,'danger'));}
function tlConfirmDanger(action,id){const e=tlGet('mcp',id);if(!e?.enabled)return;if(action==='rotate'){const input=document.getElementById('tl-new-secret');if(!input?.value.trim())return tlError('请提交新凭据。');input.value='';e.expired=false;e.health='待检测';tlState.preview='正常';}else e.enabled=false;tlState.version++;closeModal();route();tlDetail('mcp',id);toast(action==='rotate'?'凭据已轮换（内存演示），不回显':'服务器已停用（内存演示）');}
function tlAdopt(id){const e=tlLocal.find(e=>e.id===id);if(!e||e.adopted)return;tlModal('纳入团队目录',tlKv([['名称',tlEsc(e.name)],['类型',e.kind],['检测来源',tlEsc(e.path)],['授权范围','无（默认）']])+'<div class="note warn">本机凭据不会导入。技能以检测到的包版本纳入；MCP 需你重新提交凭据并配置团队连接。</div>',tlBtn('取消','closeModal()')+tlBtn('确认纳入',`tlConfirmAdopt('${id}')`,'primary'));}
function tlConfirmAdopt(id){const e=tlLocal.find(e=>e.id===id);if(!e||e.adopted)return;if(e.kind==='MCP'){closeModal();tlAdd();document.getElementById('tl-name').value=e.name;document.getElementById('tl-provider').value='本机检测';document.getElementById('tl-transport').value='打包的 stdio';document.getElementById('tl-address').value='';const button=document.querySelector('#modal button.primary');button.setAttribute('onclick',`tlFinishLocalMcp('${id}')`);return;}const s={id:'skill'+(tlSkills.length+1),name:e.name,version:e.version,hash:e.hash,source:'上传',grants:[],agents:0,next:null,description:'从执行机检测到的本机技能包纳入团队目录。',files:['SKILL.md'],history:[[e.version,e.hash,'从本机技能包纳入']],diff:'当前无新版本。'};tlSkills.push(s);e.adopted=true;tlState.version++;tlState.tab='skill';tlState.preview='正常';closeModal();route();tlDetail('skill',s.id);toast('技能已纳入，默认无授权（内存演示）');}
function tlFinishLocalMcp(id){const before=tlServers.length;tlSubmitAdd();if(tlServers.length>before){tlLocal.find(e=>e.id===id).adopted=true;route();tlDetail('mcp',tlServers[tlServers.length-1].id);}}
